add('349-a','Pessoa facilita entrada não autorizada de telefone em estabelecimento prisional.','Uso/posse e ingresso não são sinônimos; omissão funcional do319-A tem recorte próprio.','Rádio ou similar também está previsto? Sim.','Todo objeto eletrônico é telefone/radio típico por presunção? Não.')
add(351,'Terceiro promove fuga de pessoa legalmente presa.','A própria evasão do preso exige distinguir352; culpa do funcionário custodiante tem pena própria.','Medida de segurança detentiva está incluída? Sim.','Qualquer fuga por culpa de qualquer pessoa é automaticamente§4º? Não; recorte funcional.')
add(352,'Preso tenta evadir-se usando violência contra pessoa.','Fuga simples não preenche352; isso não exclui falta disciplinar ou outros crimes concretos.','Precisa conseguir sair para a conduta expressa? Não; tentar evadir-se também é previsto.','Violência só contra coisa equivale automaticamente à pessoa? Não.')
add(353,'Preso é arrebatado da custódia para ser maltratado.','Resgate com outra finalidade exige enquadramento próprio; não presumir maltrato.','Finalidade de maltratar importa? Sim.','Pena da violência pode acumular? Sim; previsão expressa.')
add(354,'Presos se amotinam perturbando ordem prisional.','Reivindicação lícita sem motim típico não é automaticamente crime.','Pluralidade de presos é característica? Sim.','Qualquer reclamação individual é354? Não.')
add(355,'Advogado trai dever profissional e prejudica interesse confiado em juízo.','Defender partes contrárias na mesma causa tem parágrafo próprio; incompetência sem dolo não é traição automática.','Sucessão de patrocínio também está prevista? Sim.','Todo resultado desfavorável prova crime do advogado? Não.')
add(356,'Advogado inutiliza documento probatório recebido nessa qualidade.','Impossibilidade justificada ou perda sem dolo não deve ser tratada como sonegação automática.','Inutilização parcial está incluída? Sim.','A qualidade em que recebeu o objeto importa? Sim.')
add(357,'Agente solicita utilidade a pretexto de influir em testemunha.','Tráfico de influência genérico332 e corrupção real têm elementos próprios.','Testemunha e perito estão no rol? Sim.','Insinuar destino da utilidade ao juiz tem aumento próprio? Sim;um terço.')
add(358,'Concorrente é ameaçado para se afastar de arrematação judicial.','Não substituir automaticamente este regime pelos tipos de licitações administrativas.','Procurar afastar é conduta expressa? Sim.','Todo leilão particular entra como arrematação judicial? Não.')
add(359,'Pessoa exerce atividade da qual foi privada por decisão judicial válida conhecida.','Sanção exclusivamente administrativa exige outro enquadramento; não presumir decisão judicial.','Suspensão judicial também está prevista? Sim.','Qualquer restrição administrativa é359? Não.')
add('359-a','Operação de crédito público é autorizada sem prévia autorização legislativa.','Limites legais e resolução do Senado têm hipóteses equiparadas; não confundir com empréstimo pessoal comum.','Crédito externo também está previsto? Sim.','Qualquer dívida privada constitui este tipo? Não.')
add('359-b','Inscrição em restos a pagar é ordenada sem empenho prévio.','Excesso de limite é alternativa típica distinta; restos a pagar regulares não são crime por si.','Pena é detenção? Sim.','Toda despesa empenhada e ainda não paga prova crime? Não.')
add('359-c','Obrigações são assumidas nos dois últimos quadrimestres sem caixa suficiente no recorte legal.','Obrigação com parcela futura e contrapartida suficiente precisa ser distinguida; não proibir todo contrato de fim de mandato.','Período é o último ano inteiro? Não;dois últimos quadrimestres.','Parcela no ano seguinte é sempre ilícita mesmo com caixa? Não; verificar condições.')
add('359-d','Despesa não autorizada por lei é ordenada com os elementos penais.','Não confundir ordenar com toda execução material ou erro contábil sem dolo.','Núcleo legal é ordenar? Sim.','Todo desacerto administrativo prova automaticamente o crime? Não.')
add('359-e','Garantia em operação de crédito é prestada sem contragarantia legal suficiente.','Contragarantia de igual valor satisfaz referência quantitativa, mas outros requisitos legais continuam.','Valor inferior é suficiente pelo texto? Não.','Tipo exige valor exatamente igual e proíbe superior? Não;igual ou superior.')
add('359-f','Agente com dever deixa de promover cancelamento de restos a pagar excessivos.','Não cancelar montante regular não é a mesma hipótese; dever e limite legal devem ser identificados.','Crime tem conduta omissiva? Sim.','Todo saldo inscrito deve ser cancelado por este artigo? Não;excesso legal importa.')
add('359-g','Ato aumenta despesa total com pessoal nos180 dias anteriores ao fim do mandato.','Não confundir prazo penal com dois quadrimestres do359-C; exceções e elementos exigem regime aplicável.','Prazo é180 dias? Sim.','Qualquer reajuste histórico prova crime sem examinar tipo e regime? Não.')
add('359-h','Títulos de dívida pública criados por lei são colocados no mercado sem registro exigido.','Apenas criação legal não basta: falta de registro é alternativa incriminadora própria.','Uma só dessas ausências pode satisfazer a alternativa típica? Sim.','Os requisitos de regularidade são escolher criação ou registro? Não;ambos no recorte legal.')
add('359-i','Agente negocia com grupo estrangeiro para provocar atos de guerra contra o País.','Diplomacia ou crítica pacífica não prova finalidade bélica; operação bélica do§2º tem pena distinta.','Finalidade de guerra/invasão importa? Sim.','Toda conversa com estrangeiro é crime? Não.')
add('359-j','Violência é praticada para desmembrar território e constituir país independente.','Debate político pacífico não satisfaz automaticamente violência/grave ameaça.','Grave ameaça é alternativa prevista? Sim.','Toda defesa abstrata de mudança territorial basta? Não.')
add('359-k','Informação ultrassecreta é entregue a destinatário legalmente indicado com risco típico.','Comunicação para expor crime ou violação de direitos humanos tem ressalva expressa no§4º; não omití-la.','Informação reservada equivale automaticamente à secreta/ultrassecreta? Não.','A finalidade de expor crime possui ressalva legal? Sim;§4º.')
add('359-l','Violência é usada para tentar abolir Estado Democrático impedindo poderes constitucionais.','Crítica,reunião pacífica ou jornalismo exigem359-T; não presumir crime pelo posicionamento político.','Tentar é verbo expresso do tipo? Sim.','Toda oposição política é abolir violentamente? Não.')
add('359-m','Agente tenta depor governo legitimamente constituído por grave ameaça.','Discordância eleitoral ou manifestação constitucional legítima não prova tentativa violenta.','Deposição precisa ocorrer para a conduta expressa? Não.','A pena do caput é igual à do359-L? Não;limite máximo distinto.')
add('359-m--2','Texto de359-M-A indica concurso formal próprio para delitos do capítulo no mesmo contexto.','Notícia oficial de9/5/2026 registra suspensão nas execuções específicas listadas; não apresentar benefício como universal definitivo.','A regra textual autoriza soma irrestrita nesse recorte? Não.','Pode aplicá-la automaticamente a toda execução apesar de decisão judicial? Não.')
add('359-m--3','Texto de359-M-B prevê redução em contexto de multidão sem financiamento nem liderança.','Liderança/financiamento afasta condição textual; controle constitucional e decisões aplicáveis impedem benefício automático.','Fração textual é1/3 a2/3? Sim.','Estar em multidão garante redução definitiva em qualquer processo? Não.')
add('359-n','Mecanismo de segurança de votação é violado para perturbar aferição do resultado.','Debate sobre eleições ou erro técnico sem elementos típicos não prova esse crime.','Violação indevida do mecanismo importa? Sim.','Toda crítica ao resultado configura interrupção eleitoral? Não.')
add('359-p','Violência psicológica impede direito político por motivo de raça.','Conflito político sem motivação discriminatória e violência típica exige outro enquadramento.','Protege só candidatas mulheres? Não;qualquer pessoa no recorte legal.','Violência sexual também é meio expresso? Sim.')
add('359-r','Instalação destinada à defesa nacional é destruída para abolir Estado Democrático.','Dano sem essa finalidade não é automaticamente este tipo; eventual outro crime precisa ser identificado.','Fim de abolir importa? Sim.','Toda falha em serviço público é sabotagem do359-R? Não.')
add('359-t','Jornalista critica poderes constitucionais ou noticia fatos no âmbito legítimo.','A ressalva não autoriza presumir violência típica como crítica, nem criminalizar manifestação pacífica por rótulo.','Crítica aos poderes é expressamente resguardada? Sim.','O artigo cria imunidade geral para todo crime do CP? Não;refere-se ao Título.')
add(360,'Cláusula histórica do CP é lida junto à evolução posterior de leis especiais.','A menção histórica a imprensa/segurança não revive leis revogadas ou não recebidas.','Ressalva histórica garante vigência eterna de toda lei citada? Não.','Cria crime autônomo novo? Não;cláusula revogatória.')
add(361,'O Código original entrou em vigor em1/1/1942, após diploma de7/12/1940.','Alteração penal de2026 tem vigência própria; não usar1942 como data de toda redação atual.','Data original e data de atualização são iguais? Não.','Conferência editorial de2026 é a data de criação do Código? Não.')
patch(351,atencao=['Promover/facilitar fuga de terceiro distingue-se da evasão do352. Fuga simples não satisfaz352, mas outros crimes concretos ou falta disciplinar podem existir; não afirmar impunidade universal de toda fuga.','§4º é modalidade culposa do funcionário incumbido da custódia/guarda.'])
patch(352,atencao=['Violência contra pessoa é elemento do352; violência só contra coisa ou fuga simples não bastam para este tipo. Outros crimes/faltas não são excluídos automaticamente.'])
patch('359-a',atencao=['Crimes contra finanças públicas inseridos pela Lei10.028/2000 no CP; não atribuir criação dos tipos à LC101 nem presumir que toda irregularidade fiscal seja crime. Normas financeiras complementares atuais exigem consulta específica.'])
patch('359-c',pontos=['Dois últimos quadrimestres do último ano do mandato/legislatura.','Obrigação com impossibilidade de pagamento no exercício ou parcela seguinte sem contrapartida suficiente de caixa, nos pressupostos legais.','Reclusão1 a4; não proibição universal de contratos ou parcelas futuras.'])
patch('359-h',atencao=['São alternativas incriminadoras: ausência de criação por lei OU ausência de registro. Regularidade exige os pressupostos aplicáveis, não escolha livre entre criação e registro.'])
patch('359-k',simples='Espionagem tem destinatários,objeto classificado e risco típicos;3 a12 anos no caput, hipóteses equiparadas/penas próprias nos§§1º a3º. Atenção:§4º expressamente exclui crime para comunicação,entrega ou publicação destinada a expor crime ou violação de direitos humanos.',pontos=['Documento/informação secretos ou ultrassecretos,nos termos legais;destinatário e risco típicos.','§1º auxílio consciente a espião;§2º violação do dever de sigilo;§3º facilitação de acesso têm recortes próprios.','§4º: não constitui crime comunicação,entrega/publicação para expor crime ou violação de direitos humanos.'])
for key in ['359-i','359-j','359-k','359-l','359-m','359-n','359-p','359-r','359-t']:note(key,'Lei14.197/2021 substituiu regime da antiga Lei de Segurança Nacional com vacância própria; não retroagir agravamento. Integrar359-T e direitos constitucionais,sem criminalizar oposição,jornalismo ou manifestação legítima por rótulo.')
for key in ['359-m--2','359-m--3']:note(key,'Lei15.402/2026: notícia oficial de9/5/2026 registra ADIs7966/7967 e suspensão nas EPs41,134,100,102,43,52,61 e72. Notícia de11/5 registra também ADIs7968/7969. Não certificada decisão de mérito final posterior nem suspensão nacional de toda execução. Texto compilado não autoriza exercício de aplicação automática do benefício.','https://noticias.stf.jus.br/postsnoticias/relator-suspende-aplicacao-da-lei-da-dosimetria-a-execucoes-penais-no-stf/')
patch('359-m--2',simples='Texto compilado de359-M-A, incluído por Lei15.402/2026: prevê concurso formal próprio para delitos deste Capítulo no mesmo contexto,mesmo com desígnio autônomo,sem cúmulo material. Distinguir texto legislativo e aplicação judicial: há controle constitucional e suspensão nas execuções específicas listadas na notícia oficial,sem certificação de mérito posterior ou benefício universal.',pontos=['Regra textual específica do mesmo Capítulo e mesmo contexto.','Remete à primeira parte do70 e veda os cúmulos expressamente indicados.','Não aplicar automaticamente em processo sujeito à suspensão/decisão judicial; consultar controle constitucional atual.'])
patch('359-m--3',simples='Texto compilado de359-M-B, incluído por Lei15.402/2026: prevê redução1/3 a2/3 no contexto de multidão,sem financiamento ou liderança. Aplicação concreta exige decisões pertinentes: notícia oficial registra suspensão em execuções específicas e ADIs; não certificado desfecho final posterior ou benefício automático.',pontos=['Requisitos textuais: delitos deste Capítulo,multidão,não financiamento/não liderança.','Fração prevista1/3 a2/3,sem redução automática por mera presença física.','Distinguir previsão legislativa e aplicação judicial,observando decisões e controle constitucional.'])
